"""Public CAD selection, shared by Fusion export and showcase assembly."""
import json
from pathlib import Path

# These body families are generated by the project's original CAD builders.
# A mixed group must be re-exported from Fusion before it can be published.
PUBLIC_PREFIXES = ("original ", "intake candidate ", "cartridge ", "frame fastening ",
                   "visual digit ", "fixed bumper ", "aft-electrical-beam", "aft-adapter",
                   "aft-crush-sleeve", "aft-bolt-", "battery-tray", "battery-end-stop",
                   "battery-strap", "battery-foot-bolt", "battery-top-", "battery-insulating-pad",
                   "pdh-bolt-", "candidate 1p5mm outer belt tread")


def public_body(name):
    return name.startswith(PUBLIC_PREFIXES) or name in PUBLIC_NAMES


ELECTRICAL = Path(__file__).resolve().parents[2] / "cad/electrical/manifest.json"
PUBLIC_NAMES = {"Continuous covered bumper envelope"} | {
    item["id"] for item in json.loads(ELECTRICAL.read_bytes())["components"] if item["role"] != "service"
}



# Each entry names the parent assembly, immediate part, and its original body.
FRAME = "Team 1780 - swerve frame and electronics supports"
MAST = "Team 1780 - lift bridge supports"
BUMPER = "Team 1780 - removable bumper mounts"
NATIVE_PARTS = {
    FRAME: {
        "Swerve frame - interchangeable drilled rail": "Tab-mounted rectangular rail",
        "Swerve frame - bolt crush sleeve": "Through-bolt crush sleeve",
        "10-32 x 2.75 socket head": "10-32 bolt envelope",
        "10-32 locknut": "10-32 locknut envelope",
        **{"Deck support - "+kind: "Body1" for kind in ("open socket pedestal", "rear stringer", "transverse member")},
    },
    MAST: {"Mast support - "+kind: "Body1" for kind in ("bridge extension", "stepped web")},
    BUMPER: {
        "Front bumper frame rail": "Box tube with welded screw landings",
        **{side+" bumper frame rail": "Body1" for side in ("Rear", "Left", "Right")},
        "M6 captive square flange barrel nut": "Body1",
        "M6 x 25 bumper socket screw": "Body1",
    },
}
MARKINGS = {f"1780 WHITE team marking {face} - visual only" for face in ("x1","x-1","y1","y-1")}


def public_occurrence(row):
    owner, part, body = row["parent"], row["component"], row["name"]
    if row["depth"] == 2:
        return NATIVE_PARTS.get(owner, {}).get(part) == body
    if row["depth"] != 1 or owner != part:
        return False
    if owner in MARKINGS:
        return body in {"visual digit "+digit for digit in "1780"}
    if owner == "Continuous bumper native display v2":
        return body == "Continuous covered bumper envelope"
    if row.get("sourceRootIndex") is None or owner.startswith("MAXSwerve"):
        return False
    return public_body(body)
